package com.collabspace.entity;
import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="direct_messages",indexes=@Index(name="idx_dm_conversation_created",columnList="conversation_id,created_at")) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class DirectMessage { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private DirectConversation conversation; @ManyToOne(fetch=FetchType.LAZY,optional=false) private User sender; @Column(nullable=false,length=4000) private String content; @Column(nullable=false,updatable=false) @Builder.Default private Instant createdAt=Instant.now(); @Column(nullable=false) @Builder.Default private Instant updatedAt=Instant.now(); @Column(nullable=false) @Builder.Default private boolean edited=false; @Column(nullable=false) @Builder.Default private boolean deleted=false; @Enumerated(EnumType.STRING) @Column(nullable=false) @Builder.Default private ReadStatus readStatus=ReadStatus.SENT; @PreUpdate void touch(){updatedAt=Instant.now();} }